import socket

#: How long to wait for the service before giving up.
TIMEOUT_S = 0.005
MAX_RETRIES = 3


class StatusClient:
    """Fetches a status line from the service over TCP."""

    def __init__(
        self, host: str, port: int, timeout_s: float = TIMEOUT_S, max_retries: int = MAX_RETRIES
    ) -> None:
        self.host = host
        self.port = port
        self.timeout_s = timeout_s
        self.max_retries = max_retries

    def fetch_status(self) -> bytes:
        """Return the service's status line.

        Raises:
            OSError: On connect failure or timeout after all retries are exhausted.
        """
        last_exc: OSError | None = None
        for _ in range(self.max_retries):
            try:
                sock = socket.create_connection(
                    (self.host, self.port), timeout=self.timeout_s
                )
                try:
                    sock.settimeout(self.timeout_s)
                    sock.sendall(b"STATUS\n")
                    return sock.recv(64)
                finally:
                    sock.close()
            except OSError as exc:
                last_exc = exc

        if last_exc is not None:
            raise last_exc
        raise OSError("Fetch status failed")
